arguments.command:
source /opt/miniconda3/bin/activate testbed && python -c "
import sys
# Check if any custom modules are being loaded
for name, module in sys.modules.items():
    if module and hasattr(module, '__file__'):
        f = module.__file__
        if f and 'site-packages' in f and not name.startswith('_'):
            print(f'{name}: {f}')
" 2>&1 | head -30

